// CSD_RATIONALE_BEGIN
// Strategy: GenerateWithPrefixAndManagedSpan with task-specific guidance.
//
// (1) CURRENCY-LABEL FIX: Failing outputs included currency symbols as math
//     variables. Guidance clarifies: currency labels like $ are NOT variables —
//     for a price shown as '{cur}{price}', use only 'price' in EXPR, never 'cur'.
//
// (2) int() MISUSE FIX: Model was wrapping purely integer arithmetic in int(),
//     causing parse failures. Guidance restricts int() to conversion of fractional
//     operations only.
//
// (3) SYNTAX/SPAN-CLOSURE FIX: Failing outputs showed multi-sentence explanations
//     inside <<...>>, burning budget and leaving the span unterminated. Guidance
//     stresses: keep EXPR compact, no spaces, no words, just the arithmetic
//     expression. Explicitly forbids writing <<...>> during intermediate steps.
//
// Structure: GenerateWithPrefixAndManagedSpan at prefixBudget=78% (702/900),
// boostAmount=8.0, narrowThreshold=6. Forces << entry by step 702 and reserves
// 198 steps for constrained closure. cost=maxSteps conservatively satisfies
// all postconditions.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Initialization: insideConstrainedOut := insideConstrained and
//   currentConstrainedOut := currentConstrained, valid by method preconditions.
//   When maxSteps==0, no modification occurs; invariant holds trivially.
//
//   GenerateWithPrefixAndManagedSpan postcondition directly guarantees:
//     !insideConstrainedOut ==> currentConstrainedOut == [] and
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//   Inside the helper:
//   - Free branch: insideConstrainedOut stays false until RenderedEndsWith "<<"
//     triggers, at which point currentConstrainedOut:=[] is valid by
//     parser.IsValidPrefix([]) (method precondition).
//   - Constrained branch: AdaptiveConstrainedStep selects parser-valid tokens;
//     AppendConstrainedToken preserves IsValidPrefix by contract; CloseSpanIfComplete
//     sets insideConstrainedOut:=false, currentConstrainedOut:=[] (vacuously valid)
//     or leaves the invariant intact when not closing (inductive case).
//   No code modifies span state after the helper call.
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + maxSteps, cost <= maxSteps
//
//   GenerateWithPrefixAndManagedSpan postcondition: at most maxSteps tokens added
//   to generated, so |generated| <= |generatedPrefix| + maxSteps. Each appended
//   token (unconstrained, constrained, or forced delimiter) costs exactly one
//   step, so visible growth is bounded by the consumed token budget.
//   cost := maxSteps satisfies cost <= maxSteps.
//   Liveness: maxSteps > 0 ==> cost = maxSteps > 0 satisfies cost > 0 directly.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  helpers.AppendTaskGuidance(lm, "Solve step by step in plain text. Write the final answer at the very end as <<EXPR>>. EXPR is a single compact arithmetic expression using only: variable names without { braces }, integers, +, -, *, /, //, %, (, ), int(). KEY RULES: (1) Currency labels like $ are NOT variables — for a price shown as '{cur}{price}', use only 'price' in EXPR, never 'cur'. (2) Use int() ONLY to convert a division or fractional multiplication to integer, e.g. int(n*frac) or int(a/b). Do NOT wrap purely integer arithmetic in int(). (3) Keep EXPR compact — no spaces between tokens, no words, just the arithmetic expression. (4) Write exactly ONE <<EXPR>> at the very end of your response, not inside intermediate reasoning steps. Examples: <<n*price>>, <<n-int(n*frac)>>, <<int(100*k/n)>>, <<p1+p2+p3*frac+p4-d>>, <<int((w1+w2+w3)*price)>>.");

  var prefixBudget: nat := (maxSteps * 78) / 100;
  if prefixBudget >= maxSteps {
    prefixBudget := maxSteps - 1;
  }

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget, validTokenGroups, 8.0, 6, eosToken
  );
  generated := g;
  insideConstrainedOut := ic;
  currentConstrainedOut := cc;

  cost := maxSteps;
}
